      {
        "event_id": "lite_evt_00084",
        "explanation": "Doctor explicitly instructs not to stop immunosuppressive drugs.",
        "quote": "请**绝对不要自行停用环孢素、强的松或吗替麦考酚酯**"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00123",
        "explanation": "Doctor provides differential reasoning for ALT/AST elevation in a transplant patient.",
        "quote": "肝功能异常在长期使用环孢素的患者中较常见，可能与药物肝毒性有关，但也需排除病毒性肝炎"
      }
    ],
    "continuity_memory_focus": [
