    "patient_family_realworld_adaptation": "excellent"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00123",
          "explanation": "The doctor avoids labeling language and provides a family script that acknowledges both the low risk and the need for verification without stigmatizing the patient.",
          "quote": "建议在乙肝五项、丙肝抗体、以及以前肺结核治疗情况核实清楚前，如果家里特别担心，碗筷可以暂时分开用，不要共用牙刷、剃须刀，也避免接触血液或伤口。"
        },
        {
          "event_id": "lite_evt_00084",
          "explanation": "The doctor explicitly states the patient is not currently infectious and supports normal family contact.",
          "quote": "因此，**老人与家人共餐、共用碗筷是安全的，无需分餐或隔离**，可以放心告知家人。"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor uses non-stigmatizing, context-sensitive language that balances both the family's fear and the patient's dignity. The advice avoids labeling the patient as a source of infection and provides concrete family communication scripts, which goes beyond generic reassurance.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00123",
          "explanation": "Doctor organizes the required materials into a clear, portable list for the family to bring to the appointment.",
          "quote": "列一份“带什么”清单：\n- 最近的肝功能/肾功能化验单\n- 乙肝五项、HBV DNA报告\n- 丙肝抗体或丙肝病毒核酸结果\n- 所有药盒或用药清单\n- 肺部CT报告（或拍下最重要的几行文字）\n- 如果还能找到，以前结核治疗相关的资料"
        },
        {
          "event_id": "lite_evt_00123",
          "explanation": "The doctor provides a specific, actionable plan that addresses the family's execution barrier of not knowing what to bring.",
          "quote": "建议由一个必要照护者保管这些材料，不在家族群转发完整病历。"
        }
      ],
      "completion": "complete",
      "explanation": "The model transforms a complex set of missing records into a low-burden, executable plan with a clear, itemized list and a suggestion for a single caregiver to manage sensitive documents, directly addressing the real-world constraint of the family's conflict and the patient's privacy.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00051",
          "explanation": "The family reports that the patient feels stigmatized and is reluctant to share medical records.",
          "quote": "患者本人觉得被嫌弃，不愿继续让家属看病历"
        },
        {
          "event_id": "lite_evt_00123",
          "explanation": "The doctor identifies the family's fear of contamination and the patient's privacy as a key execution barrier.",
          "quote": "在未确认活动性传染前，不建议在家中对老人进行歧视性分餐、隔离，也不要在家族群公开完整的敏感病史。"
        }
      ],
      "completion": "partial",
      "explanation": "The model identifies the family's contamination fear and the patient's reluctance to share records, but it does not actively probe the specific family dynamics (e.g., whether they have already started separating utensils). It addresses the issue in the plan but doesn't fully discover the extent of the 'quarantine' behavior.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00123",
          "explanation": "The doctor clearly states which information is still unknown and what must be verified, setting a safe boundary.",
          "quote": "肝功能具体数值或趋势尚未完全掌握，但已列为联系医生前必须补齐的资料"
        },
        {
          "event_id": "lite_evt_00123",
          "explanation": "The doctor explains that the current plan is to safely bridge to the specialist visit without making a definitive diagnosis.",
          "quote": "当前目标是安全交接和避免自作主张，不是线上定诊断。"
        }
      ],
      "completion": "partial",
      "explanation": "The model closes the episode by listing allowed residual risks and giving a clear tracking method. However, it does not fully re-state all of the specific allowed residual risks (e.g., HBV DNA) in the final turn, making the closure a bit less explicit than a perfect one.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
